class VBase {
public:
    virtual void setup() = 0;
    VBase() { 
        // During construction, Vptr points to VBase.
        // Virtual calls resolve to VBase methods.
    }
    virtual ~VBase() = default;
};

class Derived : public VBase {
    int resource;
public:
    // Initialization Order: Base -> Vptr Set -> Members -> Body
    Derived(int r) : VBase(), resource(r) { 
        // 1. VBase() runs.
        // 2. Vptr set to Derived's table.
        // 3. Member list (resource(r)) executes.
        // 4. Constructor body runs.
    }
    void setup() override { /* ... */ }
};
// Note: If resource used raw 'new', use initializer list 
// to prevent accessing uninitialized memory in body.
